{
  "pairs": {
    "conflict_83832dc95e4684d1ea9a6a56": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states all GAEs and alternative arrangements revoked effective March 12, 2025. Claim 2 states US-sourced derivatives are not subject to duties on or after March 12, 2025. These claims are incompatible regarding the existence of exemptions post-March 12.",
      "requires_current_authority_verification": true
    },
    "conflict_57184b7231886e8f92aa550d": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states tariffs do not stack. Claim 2 states Section 232 tariffs can apply to the same product based on content (stacking). Direct contradiction on tariff stacking rules.",
      "requires_current_authority_verification": true
    },
    "conflict_faa6a0590fa11d52c10cb9ae": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states goods with multiple metals subject to only one rate (no stacking). Claim 2 states tariffs can apply to same product based on content. Direct contradiction on tariff stacking rules.",
      "requires_current_authority_verification": true
    },
    "conflict_62254e3db3c831a162d59512": {
      "classification": "complementary_or_no_conflict",
      "reason": "Both claims describe the same investigation initiation by Mexico's Ministry of Economy on Feb 16, 2026. Claim 2 elaborates on relevance for US exporters without contradicting Claim 1.",
      "requires_current_authority_verification": false
    },
    "conflict_4bfc1b73367d31b28b94f6a4": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 2 includes all data from Claim 1 plus additional countries (Indonesia, Thailand). They are consistent subset relationships.",
      "requires_current_authority_verification": false
    },
    "conflict_d20ff50139f66e9a08c72d00": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 2 is a subset of Claim 1 (missing Indonesia). Both report duty rates for the same event without contradiction.",
      "requires_current_authority_verification": false
    },
    "conflict_fe7a4117bdfc6b1ff43603ba": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 reports a single duty rate (7.42%). Claim 2 reports a range of rates per country (3.97% to 49.05%) for the same preliminary determination event. Data discrepancy on reported rates.",
      "requires_current_authority_verification": true
    },
    "conflict_c8b15f4068d7e79cc7a01f29": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 states general rate (25%). Claim 2 specifies a lower rate (10%) for specific US-sourced derivatives. These are general vs specific scope, not contradictory.",
      "requires_current_authority_verification": false
    },
    "conflict_1b367e34648d2b411e2ed098": {
      "classification": "apparent_same_scope_conflict",
      "reason": "Claim 1 states tariff applies to full value. Claim 2 states tariff applies only to steel content, not entire value. Direct contradiction on tax base.",
      "requires_current_authority_verification": true
    },
    "conflict_c3d60899c71f410bec749d95": {
      "classification": "complementary_or_no_conflict",
      "reason": "Claim 1 concerns rescinding an administrative review for a specific POR. Claim 2 concerns continuation of the underlying Orders. These are distinct administrative actions that do not contradict.",
      "requires_current_authority_verification": false
    }
  }
}
